def build_output(grid):
    n = 10
    colors_in_grid = set()
    for row in grid:
        for c in row:
            if c != 0:
                colors_in_grid.add(c)

    components_by_color = {}
    for color in colors_in_grid:
        cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
        visited = set()
        comps = []
        for r, c in cells:
            if (r, c) in visited:
                continue
            comp = set()
            to_visit = [(r, c)]
            while to_visit:
                cr, cc = to_visit.pop()
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))
                comp.add((cr, cc))
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            to_visit.append((nr, nc))
            if comp:
                cells_list = sorted(list(comp))
                r_min, c_min = cells_list[0]
                comps.append((cells_list, r_min, c_min))
        components_by_color[color] = comps

    all_comps = []
    for color, comps in components_by_color.items():
        for (cells, r_min, c_min) in comps:
            all_comps.append(((color, cells), (r_min, c_min)))

    all_comps_sorted = sorted(all_comps, key=lambda x: (x[0][0], x[1][0]))

    output_grid = [[0]*n for _ in range(n)]

    for rank, ((color_input, cells_sorted), top_left) in enumerate(all_comps_sorted):
        if color_input % 2 == 1:
            output_color = 1
        else:
            output_color = 6

        start_row = 5 + (rank // 3) * 3
        start_col = 0 if rank < 3 else 3

        r_min, c_min = top_left
        for r, c in cells_sorted:
            nr = r_min + (r - r_min) + start_row
            nc = c_min + (c - c_min) + start_col
            if 0 <= nr < n and 0 <= nc < n:
                output_grid[nr][nc] = output_color

    return output_grid

